CREATE TABLE write_guard (id BIGINT PRIMARY KEY);
INSERT INTO write_guard VALUES (1);
CREATE TABLE organization (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, code VARCHAR(60) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE access_role (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, scope VARCHAR(20) NOT NULL, permissions VARCHAR(1000) NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE customer (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, contact VARCHAR(120) NOT NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE account (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, display_name VARCHAR(120) NOT NULL, password_hash VARCHAR(100) NOT NULL, role_id BIGINT NOT NULL, org_id BIGINT NULL, customer_id BIGINT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(role_id) REFERENCES access_role(id), FOREIGN KEY(org_id) REFERENCES organization(id), FOREIGN KEY(customer_id) REFERENCES customer(id));
CREATE TABLE dictionary_entry (id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(30) NOT NULL, code VARCHAR(60) NOT NULL, label VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0, UNIQUE(kind,code));
CREATE TABLE system_setting (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL, value VARCHAR(200) NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE nav_menu (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, label VARCHAR(120) NOT NULL, permission VARCHAR(60) NOT NULL, position INT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE asset (id BIGINT AUTO_INCREMENT PRIMARY KEY, serial VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, category VARCHAR(60) NOT NULL, purchase_cents BIGINT NOT NULL, org_id BIGINT NULL, state VARCHAR(30) NOT NULL, changed_on DATE NOT NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE asset_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, asset_id BIGINT NOT NULL, org_id BIGINT NULL, action VARCHAR(40) NOT NULL, note VARCHAR(400) NOT NULL, actor_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(asset_id) REFERENCES asset(id));
CREATE TABLE rate_version (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, daily_cents BIGINT NOT NULL, hq_bps INT NOT NULL, effective_on DATE NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE rental_contract (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, rate_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, start_on DATE NOT NULL, end_on DATE NOT NULL, daily_cents BIGINT NOT NULL, hq_bps INT NOT NULL, rate_name VARCHAR(120) NOT NULL, customer_name VARCHAR(120) NOT NULL, asset_name VARCHAR(120) NOT NULL, asset_serial VARCHAR(60) NOT NULL, delivery_state VARCHAR(30) NOT NULL DEFAULT 'WAITING', delivered_on DATE NULL, delivery_note VARCHAR(400) NULL, state VARCHAR(30) NOT NULL, return_on DATE NULL, return_note VARCHAR(400) NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(org_id) REFERENCES organization(id), FOREIGN KEY(customer_id) REFERENCES customer(id), FOREIGN KEY(asset_id) REFERENCES asset(id), FOREIGN KEY(rate_id) REFERENCES rate_version(id));
CREATE TABLE bill (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, contract_id BIGINT NOT NULL, start_on DATE NOT NULL, end_on DATE NOT NULL, due_on DATE NOT NULL, amount_cents BIGINT NOT NULL, paid_cents BIGINT NOT NULL DEFAULT 0, UNIQUE(contract_id,start_on), FOREIGN KEY(contract_id) REFERENCES rental_contract(id));
CREATE TABLE receipt (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, bill_id BIGINT NOT NULL, amount_cents BIGINT NOT NULL, received_on DATE NOT NULL, reference VARCHAR(120) NOT NULL, note VARCHAR(400) NOT NULL, state VARCHAR(30) NOT NULL, creator_id BIGINT NOT NULL, reviewer_id BIGINT NULL, version BIGINT NOT NULL DEFAULT 0, UNIQUE(org_id,reference), FOREIGN KEY(bill_id) REFERENCES bill(id));
CREATE TABLE operating_cost (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, category VARCHAR(60) NOT NULL, amount_cents BIGINT NOT NULL, incurred_on DATE NOT NULL, reference VARCHAR(120) NOT NULL, note VARCHAR(400) NOT NULL, state VARCHAR(30) NOT NULL, creator_id BIGINT NOT NULL, reviewer_id BIGINT NULL, version BIGINT NOT NULL DEFAULT 0, UNIQUE(org_id,reference), FOREIGN KEY(asset_id) REFERENCES asset(id));
CREATE TABLE settlement (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, month_on DATE NOT NULL, collected_cents BIGINT NOT NULL, hq_gross_cents BIGINT NOT NULL, cost_cents BIGINT NOT NULL, hq_net_cents BIGINT NOT NULL, state VARCHAR(30) NOT NULL, creator_id BIGINT NOT NULL, reviewer_id BIGINT NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(org_id) REFERENCES organization(id));
CREATE TABLE settlement_item (id BIGINT AUTO_INCREMENT PRIMARY KEY, settlement_id BIGINT NOT NULL, item_kind VARCHAR(20) NOT NULL, source_id BIGINT NOT NULL, amount_cents BIGINT NOT NULL, hq_share_cents BIGINT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(settlement_id) REFERENCES settlement(id));
CREATE INDEX idx_settlement_source ON settlement_item(item_kind,source_id,active);
CREATE TABLE transfer_entry (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, settlement_id BIGINT NOT NULL, action VARCHAR(20) NOT NULL, direction VARCHAR(20) NOT NULL, amount_cents BIGINT NOT NULL, transferred_on DATE NOT NULL, reference VARCHAR(120) NOT NULL, note VARCHAR(400) NOT NULL, actor_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(settlement_id) REFERENCES settlement(id));
CREATE TABLE risk_case (id BIGINT AUTO_INCREMENT PRIMARY KEY, org_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL, asset_id BIGINT NULL, owner_id BIGINT NOT NULL, next_on DATE NOT NULL, state VARCHAR(20) NOT NULL, version BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(org_id) REFERENCES organization(id), FOREIGN KEY(owner_id) REFERENCES account(id));
CREATE TABLE case_note (id BIGINT AUTO_INCREMENT PRIMARY KEY, case_id BIGINT NOT NULL, note VARCHAR(400) NOT NULL, actor_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(case_id) REFERENCES risk_case(id));
CREATE TABLE audit_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NOT NULL, org_id BIGINT NULL, action VARCHAR(60) NOT NULL, object_type VARCHAR(60) NOT NULL, object_id BIGINT NOT NULL, note VARCHAR(400) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_asset_org_state ON asset(org_id,state);
CREATE INDEX idx_contract_scope ON rental_contract(org_id,customer_id,state);
CREATE INDEX idx_bill_scope_due ON bill(org_id,customer_id,due_on);
CREATE INDEX idx_receipt_month ON receipt(org_id,received_on,state);
CREATE INDEX idx_cost_month ON operating_cost(org_id,incurred_on,state);
CREATE INDEX idx_audit_org ON audit_event(org_id,id);
CREATE TABLE contract_event (id BIGINT AUTO_INCREMENT PRIMARY KEY, contract_id BIGINT NOT NULL, action VARCHAR(40) NOT NULL, note VARCHAR(400) NOT NULL, actor_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(contract_id) REFERENCES rental_contract(id));
